import { COUNTRY_PATHS } from './countries'

const TOTAL_COUNTRIES = 249

function parseVisited(text) {
  const visited = {}
  const parts = String(text || '').toUpperCase().split(/[^A-Z]+/)
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].length === 2) visited[parts[i]] = true
  }
  return visited
}

function daysUntil(dateText) {
  const match = String(dateText || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (!match) return { show: true, label: 'SET TRIP DATE' }
  const target = Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
  const days = Math.ceil((target - Date.now()) / 86400000)
  if (days <= 0) return { show: false, label: '' }
  return { show: true, label: days === 1 ? '1 DAY' : `${days} DAYS` }
}

function paletteFor(theme) {
  const palettes = {
    classic: { bg: '#ffffff', land: '#ffffff', visited: '#000000', stroke: '#000000', text: '#000000', border: '#000000' },
    atlas: { bg: '#f6efe1', land: '#fffaf0', visited: '#2f6f73', stroke: '#203a43', text: '#17252a', border: '#203a43' },
    midnight: { bg: '#0f172a', land: '#1e293b', visited: '#f59e0b', stroke: '#e2e8f0', text: '#f8fafc', border: '#94a3b8' },
    forest: { bg: '#eef7ed', land: '#fbfff8', visited: '#2f7d32', stroke: '#234427', text: '#14331a', border: '#2f4f2f' },
    terracotta: { bg: '#fff1e6', land: '#fffaf5', visited: '#b85c38', stroke: '#5a2e2a', text: '#3f241f', border: '#7a3d2c' },
    plum: { bg: '#f5eef8', land: '#fffaff', visited: '#6d4c8d', stroke: '#31213f', text: '#241631', border: '#513269' },
    ocean: { bg: '#eaf6f8', land: '#fbffff', visited: '#0f766e', stroke: '#134e4a', text: '#0b2f33', border: '#155e75' },
    graphite: { bg: '#f2f2f0', land: '#ffffff', visited: '#3f3f46', stroke: '#18181b', text: '#18181b', border: '#27272a' },
    candy: { bg: '#fff0f5', land: '#fffafd', visited: '#db2777', stroke: '#831843', text: '#4a1730', border: '#be185d' },
    blue: { bg: '#eef4ff', land: '#ffffff', visited: '#2563eb', stroke: '#1e3a8a', text: '#172554', border: '#1d4ed8' }
  }
  return palettes[String(theme || 'classic').toLowerCase()] || palettes.classic
}

function fitTextSize(text, maxWidth, preferred) {
  return Math.max(preferred * 0.55, Math.min(preferred, maxWidth / Math.max(1, String(text).length * 0.56)))
}

export function get(app) {
  const W = app.frame.width
  const H = app.frame.height
  const unit = Math.min(W, H) / 100
  const margin = unit * 4
  const lineWeight = Math.max(0.5, Math.min(5, Number(app.config.lineWeight || 2)))
  const palette = paletteFor(app.config.theme)
  const visited = parseVisited(app.config.visitedCountries)
  const count = Object.keys(visited).length
  const percent = Math.round((count / TOTAL_COUNTRIES) * 100)
  const next = String(app.config.nextDestination || 'Next destination')
  const countdown = daysUntil(app.config.tripStartDate)
  const titleSize = fitTextSize(next, W * 0.55, unit * 4.4)
  const smallSize = unit * 3
  const statSize = unit * 4.6
  const topH = Math.max(margin + Math.max(titleSize, smallSize * 2.2) + unit * 2, unit * 12)
  const bottomH = Math.max(statSize * 1.2 + margin, unit * 8)
  const availableW = W - margin * 2 - 2
  const availableH = H - topH - bottomH
  const mapW = Math.min(availableW, availableH * 2)
  const mapH = mapW / 2
  const mapX = margin + (W - margin * 2 - mapW) / 2 + 1
  const mapY = topH + (availableH - mapH) / 2
  const strokeWidth = (0.5 * lineWeight) / (mapW / 360)
  const showBorder = String(app.config.showBorder == null ? 'true' : app.config.showBorder) !== 'false'

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect x="0" y="0" width={W} height={H} fill={palette.bg} />
      {showBorder && <rect x={margin} y={margin} width={W - margin * 2} height={H - margin * 2} fill="none" stroke={palette.border} strokeWidth={Math.max(2, lineWeight * unit * 0.35)} />}
      <text x={margin * 1.8} y={margin + titleSize} fontFamily="PT Sans" fontSize={titleSize} fontWeight="700" fill={palette.text}>{next}</text>
      {countdown.show && (
        <g>
          <text x={W - margin * 1.8} y={margin + smallSize} fontFamily="PT Sans" fontSize={smallSize} fontWeight="700" textAnchor="end" fill={palette.text}>TIME TO GO</text>
          <text x={W - margin * 1.8} y={margin + smallSize * 2.35} fontFamily="PT Sans" fontSize={smallSize * 1.05} fontWeight="700" textAnchor="end" fill={palette.text}>{countdown.label}</text>
        </g>
      )}
      <g transform={`translate(${mapX} ${mapY}) scale(${mapW / 360})`}>
        {Object.keys(COUNTRY_PATHS).map((code) => (
          <path d={COUNTRY_PATHS[code]} fill={visited[code] ? palette.visited : palette.land} stroke={palette.stroke} strokeWidth={strokeWidth} />
        ))}
      </g>
      <text x={margin * 1.8} y={H - margin - statSize * 0.18} fontFamily="PT Sans" fontSize={statSize} fontWeight="700" fill={palette.visited}>{percent}%</text>
      <text x={margin * 1.8 + statSize * 2.45} y={H - margin - statSize * 0.25} fontFamily="PT Sans" fontSize={statSize * 0.52} fontWeight="700" fill={palette.text}>{count}/{TOTAL_COUNTRIES} VISITED</text>
    </svg>
  )
}
